int multiple(struct NUMBER *a, struct NUMBER *b, struct NUMBER *c) {
    int i, j, h, e, aj, bi;
    struct NUMBER a_abs, b_abs, d, tmp;

    clearByZero(c);

    if(getSign(a) > 0 && getSign(b) > 0){ 
        for (i = 0; i < KETA;i++){
            bi = b->n[i];
            h = 0;
            clearByZero(&d);
            for (j = 0; j < KETA;j++){
                aj = a->n[j];
                e = aj * bi + h; 
                if(j + i < KETA){ 
                    d.n[j + i] = (e % 10); 
                    e /= 10;
                    h = e; 
                }

            }
            if(h != 0){ 
                return -1;
            }
            add(c, &d, &tmp);
            copyNumber(&tmp, c);
        }
    } else if(getSign(a) > 0 && getSign(b) < 0){ 
        getAbs(b, &b_abs);
        multiple(a, &b_abs, c);
        setSign(c, -1);
    } else if(getSign(a) < 0 && getSign(b) > 0){ 
        getAbs(a, &a_abs);
        multiple(&a_abs, b, c);
        setSign(c, -1);
    } else if(getSign(a) < 0 && getSign(b) < 0){ 
        getAbs(a, &a_abs);
        getAbs(b, &b_abs);
        multiple(&a_abs, &b_abs, c);
    }

    return 0; 
},3

void sigint_catcher() { 
    kill(getpid() + 1, SIGINT); 
}

int main()
{
    int i;
    int childpid;
    int status;
    char buf[BUFSIZ];
    char dirbuf[BUFSIZ];
    char arrow[4] = "> "; 
    char **ap, *argv[10], *inputstring;
    getcwd(dirbuf, BUFSIZ); 
    printf("%s", dirbuf);   
    printf("%s", arrow);
    signal(SIGINT, sigint_catcher); 
    while (fgets(buf, BUFSIZ, stdin) != NULL) {
        buf[strlen(buf) - 1] = '\0'; 
        inputstring = buf;

        for (ap = argv; (*ap = strsep(&inputstring, " \t")) != NULL;)
            if (**ap != '\0')
                if (++ap >= &argv[10])
                    break;

        if (strcmp(argv[0], "k") == 0) { 
            kill(atoi(argv[1]), SIGINT); 
        } else if (strcmp(argv[0], "s") == 0) { 
            kill(atoi(argv[1]), SIGSTOP); 
        } else if (strcmp(argv[0], "c") == 0) { 
            kill(atoi(argv[1]), SIGCONT); 
        } else if (strcmp(argv[0], "cd") == 0) { 
            if (argv[1] == NULL) { 
                chdir(getenv("HOME")); 
            } else {
                chdir(argv[1]); 
            }
        } else if (strcmp(argv[0], "exit") == 0) { 
            exit(0); 
        } else if ((childpid = fork()) == 0) { 

            execv(argv[0], argv); 
            exit(0); 
        } else {

            wait(&status); 
            printf("status:%04x\n", status); 
        }
        getcwd(dirbuf, BUFSIZ); 
        printf("%s", dirbuf);   
        printf("%s", arrow);
    }
},3

int BinaryToDecimal( int binary );

int main()
{
    int binary;

