int BinaryToDecimal( int binary )
{
    int PowerOfTwo = 1;
    int decimal = 0;

    while(binary != 0)
    {
        decimal += (binary % 10) * PowerOfTwo;                  
        binary /= 10;
        PowerOfTwo = PowerOfTwo << 1;                           
    }
    return decimal;
}
