#define MAX 40


void merge_string(char *source1, char *source2, char *target) {
  while (*source1 != '\0') {
    *target = *source1;
    source1++;
    target++;
  }

  while (*source2 != '\0') {
    *target = *source2;
    source2++;
    target++;
  }

  *target = '\0';
}

