typedef struct n
{ 
    int key;
    struct n *prev, *next; 
}list;
void sort_insertion(list** head, int n)
{
    list* node=(list*)malloc(sizeof(list));
    node->key=n;
    node->next=NULL;
    node->prev=NULL;
    if(*head==NULL)
        *head=node;
    else if(node->key <= (*head)->key)
    {
        (*head)->prev=node;
        node->next=*head;
        *head=node;
    }
    else
    {
        list* temp=*head;
        while(temp->next != NULL && temp->next->key < node->key)
            temp=temp->next;
        node->prev=temp;
        node->next=temp->next;
        temp->next=node;
        if(node->next!=NULL)
            node->next->prev=node;
    }
}
void seq_insertion(list** head, int n)
{
    list* dll=(list*)malloc(sizeof(list));
    dll->key=n;
    dll->next=*head;
    dll->prev=NULL;
    if (*head!=NULL)
        (*head)->prev=dll;
    *head=dll;
}
list* search_node(list* head, int n) 
{
    list* dll=head;
    while (dll!=NULL)
    {
        if(dll->key==n)
            return dll;
        dll=dll->next;
    }
    return NULL;
}
void deletion(list** head, list* del)
{
    if (*head==del)
        *head=del->next;
    else 
    {
        if (del->next!=NULL)
            del->next->prev=del->prev;
        if (del->prev!=NULL)
            del->prev->next=del->next;
    }
    free(del);
}
void printfwd(list* head)
{
    list* dll=head;
    while (dll!=NULL)
    {
        printf("%d  ",dll->key);
        dll=dll->next;
    }
}
void printrev(list* head)
{
    list* dll=head;
    while (dll->next!=NULL)
        dll=dll->next;
    while(dll!=NULL)
    {
        printf("%d  ",dll->key);
        dll=dll->prev;
    }
}
int main()
{
    while (1)
    {
