    iRet = Count(First,Last);

    printf("\nNumber of lements are %d\n",iRet);

    DeleteLast(&First,&Last);
    DeleteFirst(&First,&Last);

    printf("Contents of linked lista are \n");
    Display(First, Last);

        return 0;
}
