int Frequency(char str[], char ch)
{
    int iCnt = 0, i = 0;

    if(str == NULL)
    {
        return -1;
    }


    while(str[i] != '\0')
    {
        if(str[i] == ch)
        {
            iCnt++;
        }
        i++;
    }


    for(i = 0; str[i] != '\0'; i++)
    {
        if(str[i] == ch)
        {
            iCnt++;
        }
    }

    while(*str != '\0')
    {
        if(*str == ch)
        {
            iCnt++;
        }
        str++;
    }


    return iCnt;
}

