int CountOne(int iValue)
{
    int iRem = 0;

    int iCnt = 0;

    if(iValue < 0)
    {
        iValue = -iValue;
    }

    while(iValue != 0)
    {
        iRem = iValue % 2;

    if(iRem == 1)
        {
            iCnt++;
        }
        iValue = iValue / 2;
    }
    return iCnt;
}
