void selectionsort(int numbers[],int array_size)
{
    int i,j,T,min;
    count++;
    for(i=0;i<array_size;i++)
    {
        count++;
        min=i;
        count++;
        for(j=i+1;j<array_size;j++)
        {
            count++;
            if(numbers[j]<numbers[min])
            {
                count++;
                min=j;
                count++;
            }
        }
        count++;
        if(i!=min)
        {
        count++;
        T=numbers[min];
        count++;
        numbers[min]=numbers[i];
        count++;
        numbers[i]=T;
        count++;
        }
    }
}
