        perror("file openning error");
        return 1;
    }

    if(lseek(rfd, offset, SEEK_SET) == -1) {
        perror("lseek error");
        close(rfd);
        return 1;
    }

    while(read(rfd, &c, 1) !=0 && count < readbyte) {
        write(1, &c, 1);
        count++;
    }

    puts("file read success");

    close(rfd);

    return 0;
