    for(i=0; i<R; i++)
    {
        for(j=0; j<C; j++)
        {
            scanf("%d", &input_matrix[i][j]);
        }
    }


    printf("\nOriginal Matrix is as follows:- \n");
    display(input_matrix);


    printf("\nUpper Triangular Matrix is as follows:- \n");
