#define CAPACITY 5
int stack[CAPACITY], top=-1;

void push(int item);
int pop();
void traverse();

int isFull();
int isEmpty();
int main()
{
    while(1)
    {
        int ch, item;
        printf("1. Push \n");
        printf("2. Pop\n");
        printf("3. Traverse \n");
        printf("4. Exit\n");
        printf("Enter your choice : ");
        scanf("%d", &ch);

        switch (ch)
        {
        case 1:
            printf("Enter element to push\n");
            scanf("%d", &item);
            push(item);
            break;
        case 2:
            item = pop();
            if(item == 0)
            {
                printf("Stack is underflow\n");
            }
            else
            {
                printf("Popped item is %d \n", item);
            }
            break;
        case 3:
            traverse();
            break;
        case 4:
            exit(0);
            break;
        default:
            printf("Invalid Input\n");
        }
    }
    return 0;
}

void push(int ele)
{
    if(isFull())
    {
        printf("Stack is Full \n");
    }
    else
    {
        top++;
        stack[top] = ele;
        printf("%d pushed \n", ele);
    }
}

int pop()
{
    if(isEmpty())
    {
        return 0;
    }
    else
    {
        return stack[top--];
    }
}

void traverse()
{
    if(isEmpty())
    {
        printf("Stack is Empty\n");
    }
    else
    {
        int i;
        for(i = 0; i<=top; i++)
        {
            printf("%d \n", stack[i]);
        }
    }
}


int isFull()
{
    if(top == CAPACITY -1)
    {
        return 1;
    }
    else
    {
        return 0;
    }
}

int isEmpty()
{
    if(top == -1)
    {
        return 1;
    }
    else
    {
        return 0;
    }
}
