    while (fscanf(arq, "%c", &aux) != EOF)
    {
        i++;
    }

    texto = malloc((i+1) * sizeof(char));

    rewind(arq);

    i = 0;

    while (fscanf(arq, "%c", &aux) != EOF)
    {
        texto[i] = aux;
        i++;
    }
    texto[i] = '\0';


    for (int j = 0; j < i; j++)
    {
        switch (texto[j])
        {
            case 'a':
