                texto[j] = 'E';
                break;

            case 'i':
                texto[j] = 'I';
                break;

            case 'o':
                texto[j] = 'O';
                break;

            case 'u':
                texto[j] = 'U';
                break;

            default:
                break;
        }
    }

    rewind(arq);
    fprintf(arq, "%s", texto);
    fclose(arq);

