                espaco = true;
            }

            else if (aux == ',' || aux == '.' || aux == ';' || aux == ':' || aux == '?' || aux == '!')
            {
                pontuacao = true;
            }

            else if (aux == '\n')
            {
                enter = true;
            }

            else
            {
                qtd.chars++;
            }

            if ((espaco == true || pontuacao == true || enter == true) &&\
                (aux != ' ' && aux != '\n' && aux != ',' && aux != '.' && aux != ';' && aux != ':' && aux != '?' && aux != '!'))
                {
                    qtd.palavras++;

                    espaco = false;
                    pontuacao = false;
                    enter = false;
                }
        }
    }

    printf("\n%s:\n", argv[1]);
    printf("\t-> chars: %i\n", qtd.chars);
    printf("\t-> palavras: %i\n", qtd.palavras);
    printf("\t-> linhas: %i\n", qtd.linhas);

    return 0;
