    for (int i = 0; i <= 10; i++) {
        int valorJaInseridoUniao = 0;

        for (int j = 0; j < 10; j++) {

            if (vet2[i] == uniao[j]) {
                valorJaInseridoUniao = 1;
            }
        }

        if (valorJaInseridoUniao == 0) {
            uniao[i + 10] = vet2[i];
        }
