{
    int ct=get_count();
    int temp=size;
    int i,k,ch=1,id1;
    if(ct>=size)
    {
        k=0;
        for(i=0;i<16 && size>0;i++)
        {
            if(Mem[i]==0)
            {
                Mem[i]=id;
                size=size-1;
                t[index1].indices[k]=i;
                k++;
            }
        }
        t[index1].id=id;
        t[index1].size=temp;
        t[index1].indices[k]=-1;
        index1=index1+1;
    }
    else
