{
    if(f==-1 && r==-1)
    {
        f=f+1;
        r=r+1;
        Queue[r]=c;
    }
    else
    {
        r=r+1;
        Queue[r]=c;
    }
}
char dequeue()
{
    char c;
    if(r!=-1 && f!=-1)
    {
        c=Queue[f];
        f=f+1;
        return(c);
    }
}
int isempty()
{
    if(r==-1)
        return(1);
    else
        return(0);
}
void main()
{
    int n,i,j,temp,min,k,k1,init_temp,sum=0,T,flag=0,set=0;
    float Waiting_time;
    char s[10];
    printf("\nEnter time slice : ");
    scanf("%d",&T);
    printf("\nEnter the number of processess : ");
    scanf("%d",&n);
    struct process p[n];
    for(i=0;i<n;i++)
    {
        printf("\nEnter name : ");
        scanf("%s",p[i].name);
        printf("\nEnter AT : ");
        scanf("%d",&p[i].AT);
        printf("\nEnter BT : ");
        scanf("%d",&p[i].BT);
        p[i].CT=0;
        p[i].status=0;
        p[i].BT1=p[i].BT;
    }
    for(i=0;i<n;i++)
    {
        for(j=i+1;j<n;j++)
        {
            if(p[i].AT>p[j].AT)
            {
                temp=p[i].AT;
                p[i].AT=p[j].AT;
                p[j].AT=temp;
                temp=p[i].BT;
                p[i].BT=p[j].BT;
                p[j].BT=temp;
                temp=p[i].BT1;
                p[i].BT1=p[j].BT1;
                p[j].BT1=temp;
                strcpy(s,p[i].name);
                strcpy(p[i].name,p[j].name);
                strcpy(p[j].name,s);
            }
        }
    }
    k=0;
    temp=0;
    while(isempty())
    {
        for(i=0;i<n;i++)
        {
            if(p[i].AT<=temp)
            {
                enqueue(p[i].name[0]);
                break;
            }
        }
        if(isempty())
            temp++;
    }
    while(k<n)
