    }
    int sparse_matrix[row][column];

    int i, j, size = 0;
    printf("Enter the values for Sparse matrix\n");

    for(i = 0; i < row; i++ ) {
        for(j = 0; j < column; j++) {
            printf("Enter the value of Row %d\t Column %d\n",i,j);
            scanf("%d",&sparse_matrix[i][j]);
