}

typedef struct{
    short int vert;
    short int horiz;
    short int hei;
}offsets;
offsets move[6];


int min;
int n;

int bfs(char*** maze,int*** d,int sr,int sc,int sh){
    rear=-1;front=-1;

    int arrive=0;
    element position;
    position.row = sr;
    position.col = sc;
    position.hei = sh;


    addq(position);
    int i,j,k;
    for(i=0;i<n/2+1;i++){
        for(j=0;j<n+2;j++){
            for(k=0;k<n+2;k++){
                d[i][j][k]=MAX;
            }
        }
    }
    d[sh][sr][sc]=0;


    int nr,nc,nh;
    int row,col,hei;
    while(rear!=front){

        position = deleteq();
        row = position.row;
        col = position.col;
        hei = position.hei;


        if(maze[hei][row][col]=='F'){

            if(min>d[hei][row][col]){
                min = d[hei][row][col];
            }
            min = d[hei][row][col];

            arrive=1;
        }

        if(maze[hei][row][col]=='U' || maze[hei][row][col]=='D'){
            int upanddown=-1;
            if(maze[hei][row][col]=='U'){

                upanddown=1;
            }


            nr = row;
            nc = col;
            nh = hei+upanddown;

            if(nh>=0){
                if (maze[nh][nr][nc]!='X' && d[nh][nr][nc]>d[hei][row][col]+1){
                    d[nh][nr][nc]=d[hei][row][col]+1;
                    if(maze[nh][nr][nc]=='T'){
                        d[nh][nr][nc]=d[nh][nr][nc]+2;
                    }
                    element nextposition;
                    nextposition.row=nr;nextposition.col=nc;nextposition.hei=nh;
                    addq(nextposition);
                }
            }

        }

        for(i=0;i<4;i++){
            nr = row+move[i].vert;
            nc = col+move[i].horiz;
            nh = hei+move[i].hei;

            if (maze[nh][nr][nc]!='X' && d[nh][nr][nc]>d[hei][row][col]+1){
                d[nh][nr][nc]=d[hei][row][col]+1;
                if(maze[nh][nr][nc]=='T'){
                    d[nh][nr][nc]=d[nh][nr][nc]+2;
                }
                element nextposition;
                nextposition.row=nr;nextposition.col=nc;nextposition.hei=nh;
                addq(nextposition);
            }

        }


    }
    return arrive;
}
int pathnum=0;

void dfs(char*** maze,char*** mark,char*** road,int row,int col,int hei,int count){

    int i,j,k;

    if(count>=(min+5)){
        return;
    }
    else{
        int i;
        int nh,nr,nc;
        for(i=0;i<4;i++){
            nr = row+move[i].vert;
            nc = col+move[i].horiz;
            nh = hei+move[i].hei;
            if(mark[nh][nr][nc]!='X'){
                mark[nh][nr][nc]='X';
                road[nh][nr][nc]='*';
                if(maze[nh][nr][nc]=='T'){
                    dfs(maze,mark,road,nr,nc,nh,count+3);
                }

                else{
                    dfs(maze,mark,road,nr,nc,nh,count+1);
                }
                mark[nh][nr][nc]=maze[nh][nr][nc];
                road[nh][nr][nc]=maze[nh][nr][nc];

            }
        }
        if(maze[hei][row][col]=='U'){
            if(mark[hei+1][row][col]!='X'){
                mark[hei+1][row][col]='X';
                road[hei+1][row][col]='*';
                if(maze[hei+1][row][col]=='T'){

                    dfs(maze,mark,road,row,col,hei+1,count+3);

                }
                else if(maze[hei+1][row][col]=='F'){
                    pathnum++;
                }
                else{
                    dfs(maze,mark,road,row,col,hei+1,count+1);
                }
                mark[hei+1][row][col]=maze[hei+1][row][col];
                road[hei+1][row][col]=maze[hei+1][row][col];
            }



        }
        else if(maze[hei][row][col]=='D' && hei>0){
            if(mark[hei-1][row][col]!='X'){

                mark[hei-1][row][col]='X';
                road[hei-1][row][col]='*';
                if(mark[hei-1][row][col]='T'){
                    dfs(maze,mark,road,row,col,hei-1,count+3);
                }
                else{

                    dfs(maze,mark,road,row,col,hei-1,count+1);
                }
                mark[hei-1][row][col]=maze[hei-1][row][col];
                road[hei-1][row][col]=maze[hei-1][row][col];
            }
        }

    }

}

