struct adjLNode
{
    int dest;
    struct adjLNode* next;

};
struct adjList
{
    struct adjLNode* head;
};
struct Graph
{
    int V;
    struct adjList* arr;
};
struct Graph* createGraph(int V)
{
    struct Graph* graph=(struct Graph*)malloc(sizeof(struct Graph));
    graph->V=V;
    graph->arr=(struct adjList*)malloc(V*sizeof(struct adjList));
    for(int i=0;i<V;i++)
    {
        graph->arr[i].head=NULL;
    }
    return graph;
}
void addEdge(struct Graph* graph,int src,int dst)
{
    struct adjLNode* newNode=(struct adjLNode*)malloc(sizeof(struct adjLNode));
    newNode->dest=dst;
    newNode->next=graph->arr[src].head;
    graph->arr[src].head=newNode;
    struct adjLNode* newNode2=(struct adjLNode*)malloc(sizeof(struct adjLNode));
    newNode2->dest=src;
    newNode2->next=graph->arr[dst].head;
    graph->arr[dst].head=newNode2;

}
void printGraph(struct Graph* graph)
{
    for(int i=0;i<graph->V;i++)
    {
        struct adjLNode* temp=graph->arr[i].head;
        printf("The connected vertices to the vertex %d are- \n",i);
        while(temp)
        {
            printf("%d ",temp->dest);
            temp=temp->next;
        }
        printf("\n");
    }
}
int main()
{
    int V;
    printf("Please enter the number of vertices to your graph\n");
    scanf("%d",&V);
    struct Graph* graph=createGraph(V);
    int n;
    printf("Please enter the number of Edges you want the graph to have\n");
    scanf("%d",&n);
    for(int i=0;i<n;i++)
    {
        int src,dst;
        scanf("%d %d",&src,&dst);
        addEdge(graph,src,dst);
    }
    printGraph(graph);
    return 0;
},61

typedef struct Node* nptr;
typedef struct Node
{
    nptr llink;
    nptr rlink;
    int ele;
}node;

nptr createNode(int x)
{
    nptr temp=(nptr)malloc(sizeof(node));
    temp->ele=x;
    temp->llink=NULL;
    temp->rlink=NULL;
    return temp;
}

void insertst(nptr* start,nptr* end,int x)
{
    nptr temp=createNode(x);

    if(!*start)
    {
        *start=temp;
        *end=temp;
    }
    else
    {
        temp->rlink=*start;
        (*start)->llink=temp;
        *start=temp;
    }
}

void inserten(nptr* start,nptr* end,int x)
{
    nptr temp=createNode(x);

    if(!*end)
    {
        *start=temp; *end=temp; 
        return;
    }
    else
    {
        (*end)->rlink=temp;
        temp->llink=*end;
        *end=temp;
    }
}

int delst(nptr* start,nptr* end)
{
    if(!*start)
    {
        printf("Underflow!!\n"); 
        return -99;
    }

    nptr temp; int x;
    temp=*start;
    x=temp->ele;

    if(!((*start)->rlink))
    {
        *end=*start=NULL;
        free(temp);
        return x;
    }

    *start=(*start)->rlink;
    (*start)->llink=NULL;

    free(temp);
    return x;
}

int delen(nptr* start,nptr* end)
{
    if(!*end)
    {
        printf("Underflow!!\n"); 
        return -99;
    }

    nptr temp; int x;
    temp=*end;
    x=temp->ele;

    if(!((*end)->llink))
    {
        *end=*start=NULL;
        free(temp);
        return x;
    }

    *end=(*end)->llink;
    (*end)->rlink=NULL;

    free(temp);
    return x;
}

void disp(nptr front)
{
    printf("NULL <--->");
    for(nptr i=front;i;i=i->rlink)
        printf(" %d <---> ",i->ele);

    printf("NULL \n");
}

int main()
{
    printf("1:Insert@start 2:Insert@end 3:Delete@start\n4:Delete@end 5:Display 6:Exit\n");
    int i=1,ch,ele;

    nptr start=NULL,end=NULL;

    while(i)
    {
        printf("Command: "); 
        scanf("%d",&ch);

        switch(ch)
        {
            case 1:
                    printf("Enter element to insert: ");
                    scanf("%d",&ele);
                    insertst(&start,&end,ele);
                    break;

            case 2:
                    printf("Enter element to insert: ");
                    scanf("%d",&ele);
                    inserten(&start,&end,ele);
                    break;

            case 3:
                    ele=delst(&start,&end);
                    if(ele!=-99) 
                        printf("Deleted %d\n",ele);
                    break;

            case 4:
                    ele=delen(&start,&end);
                    if(ele!=-99) 
                        printf("Deleted %d\n",ele);
                    break;

            case 5:
                    disp(start);
                    break;

            case 6:
                    i=0; break;
        }

    }
