double add(double L[], int n)
{
    double sum = 0;

    for(int i = 0 ; i < n ; i++)
        sum += L[i];

    return sum;
}

int Lsearch(int arr[], int n, int x)
{
    for(int i = 0 ; i < n ; i++)
        if(arr[i] == x)
            return i + 1;

    return -1;
}

void multiply(int a[][10], int b[][10], int m, int n, int p, int q)
{
    int f[10][10], sum = 0;

    if(n != p)
    {
        printf("Invalid Order\n");
        return;
    }

    for(int c = 0 ; c < m ; c++)
        for(int d = 0 ; d < q ; d++)
        {
            for(int k = 0 ; k < p ; k++)
                sum += a[c][k] * b[k][d];

            f[c][d] = sum;
            sum = 0;
        }

    printf("Product of matrices: \n");

    for(int c = 0 ; c < m ; c++)
    {
        for(int d = 0 ; d < q ; d++)
            printf("%d\t", f[c][d]);

        printf("\n");
    }

    printf("\n");
}

int secLar(int a[], int n)
{
    int first, second;

    first = second = -99999;

    for(int i = 0; i < n ; i++)
        if(a[i] > first)
        {
            second = first;
            first = a[i];
        }
        else if(a[i] > second && a[i] < first)
            second = a[i];

    return second;
}

