void reverse(int arr[], int size)
{
    int *start = arr , *end = arr + size - 1;

    for(int i = 0 ; i < size/2 ; i++)
    {
        int temp = *(start + i);
        *(start + i) = *(end - i);
        *(end - i) = temp;
    }
}

