void somma_armonica(int n, double* h)
{

    if(n == 1)
    {
        *h = 1.0 + *h;
    } else {       
        *h =  *h + (1.0/n);
        somma_armonica(n-1,h);     
    }

}

int main(void) 
{
    int n;
    double risultato;

    printf("Inserisci n: ");
    scanf("%d", &n);

    somma_armonica(n, &risultato);
    printf("Risultato = %lf", risultato);


    return 0;

